export interface ToolDefinition {
  /** Category id (pdf, image, dev, calc, security, file, utils) */
  cat: string;
  /** Whether this tool appears in the "Popular" section on homepage */
  popular: boolean;
  /** i18n key for the tool title */
  titleKey: string;
  /** Display name (Indonesian fallback) */
  title: string;
  /** i18n key for the tool description */
  descKey: string;
  /** Description text (Indonesian fallback) */
  desc: string;
  /** URL path */
  href: string;
  /** Theme color */
  color: string;
  /** SVG path data for the icon */
  icon: string;
  /** Display category name for search (e.g. "PDF", "Image") */
  category: string;
  /** Same as desc — used as fallback in search */
  descFallback: string;
  /** SEO-optimized page title for Google (optional — auto-derived if missing) */
  seoTitle?: string;
  /** SEO-optimized meta description for Google (optional — auto-derived if missing) */
  seoDesc?: string;
}

