/** Look up a tool by its href path */
export function getToolByHref(href) {
  return tools.find(function(tool) {
    var tHref = tool.href.endsWith('/') && tool.href.length > 1 ? tool.href.slice(0, -1) : tool.href;
    var input = href.endsWith('/') && href.length > 1 ? href.slice(0, -1) : href;
    return tHref === input;
  });
}
